	@Test
	void sequentialOrderedProducersReuseThePaidPeakIndexCapacity() throws Exception {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(64L << 10, 64L << 10);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		List<Long> retained = new ArrayList<>();
		long hits = NativeExpressionDomain.HITS.get();
		try (var fixture = new NativeRowTermDomainExecutionTest.Fixture("ordinal", "text", "result")) {
			RowState row = automaticRow(fixture);
			CopyBinding copy = fixture.countedCopy(new FunctionCall(FN.STRING_LENGTH.stringValue(), Var.of("text")), 2);
			ValuesRow[] values = { fixture.values(0, "α😀"), fixture.values(1, "α😀") };
			// Prime legitimate query-owned generated result authority before measuring optional producer claims.
			int mark = row.mark();
			assertTrue(row.bind(1, values[0].values[1]));
			assertThat(((Literal) fixture.source.lazyValue(copy.value(row))).intValue()).isEqualTo(2);
			row.rollback(mark);
			for (int opening = 0; opening < 12; opening++) {
				try (RowCursor cursor = new ExtensionCursor(SlotPlan.values(values).open(row),
						new CopyBinding[] { copy }, row)) {
					assertProjectedRows(cursor, fixture, row, List.of("α😀", "α😀"));
				}
				assertThat(row.boundMask()).isZero();
				retained.add(manager.usedBytes());
			}
			assertThat(fixture.evaluations).hasValue(13);
			assertThat(NativeExpressionDomain.HITS.get() - hits).isEqualTo(12);
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
		assertThat(manager.usedBytes()).isZero();
		assertThat(retained).as("sequential equivalent owners need the same paid peak identity-index capacity")
				.containsOnly(retained.getFirst());
	}

