	private static void assertProjectedRows(RowCursor cursor, NativeRowTermDomainExecutionTest.Fixture fixture,
			RowState row, List<String> texts) throws IOException {
		int emitted = 0;
		while (row.advance(cursor)) {
			assertThat(((Literal) fixture.source.lazyValue(row.id(0))).intValue()).isEqualTo(emitted);
			String text = texts.get(emitted);
			assertThat(((Literal) fixture.source.lazyValue(row.id(2))).intValue())
					.isEqualTo(text.codePointCount(0, text.length()));
			assertThat(((FactorizedRowCursor) cursor).multiplicity()).isEqualTo(1L);
			emitted++;
		}
		assertThat(emitted).isEqualTo(texts.size());
	}

	@Test
	void reorderedBatchSelectionDoesNotInheritAProducerOrderProof() {
		try (var fixture = new NativeRowTermDomainExecutionTest.Fixture("ordinal", "left", "right", "result")) {
			LmdbNativeCompiledBoolean filter = fixture.countedFilter(new FunctionCall(FN.CONTAINS.stringValue(),
					new FunctionCall(FN.CONCAT.stringValue(), Var.of("left"), Var.of("right")), Var.of("right")));
			NativeBatch batch = new NativeBatch(4, 128);
			Arrays.fill(batch.slots, LmdbNativeAggregateCompiler.UNKNOWN);
			List<ValuesRow> values = fixture.repeatedRows();
			for (int index = 0; index < values.size(); index++) {
				ValuesRow value = values.get(index);
				for (int cell = 0; cell < value.slots.length; cell++) {
					batch.set(value.slots[cell], index, value.values[cell]);
				}
			}
			batch.finishRows(values.size());
			for (int index = 0; index < 128; index++) {
				batch.selection[index] = 127 - index;
			}
			assertThat(filter.selectBatch(batch, batch.selection, 128, automaticRow(fixture))).isEqualTo(128);
			for (int index = 0; index < 128; index++) {
				assertThat(batch.selection[index]).isEqualTo(127 - index);
			}
			assertThat(fixture.evaluations).hasValue(128);
		}
	}

