	private static void assertUncachedInput(boolean unknown) throws Exception {
		String previousBudget = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(64L << 10, 64L << 10);
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "4096");
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		long spills = NativeExpressionDomain.SPILL_FILES_CREATED.get();
		long reads = NativeExpressionDomain.IO_READ_OPERATIONS.get();
		long writes = NativeExpressionDomain.IO_WRITE_OPERATIONS.get();
		try (var fixture = new NativeRowTermDomainExecutionTest.Fixture("ordinal", "text", "result")) {
			List<ValuesRow> values = new ArrayList<>();
			for (int ordinal = 0; ordinal < 128; ordinal++) {
				values.add(fixture.values(ordinal, "unique-" + ordinal + "😀"));
			}
			RowState row = automaticRow(fixture);
			CopyBinding copy = fixture.countedCopy(new FunctionCall(FN.STRING_LENGTH.stringValue(), Var.of("text")), 2);
			RowCursor input = SlotPlan.values(values.toArray(ValuesRow[]::new)).open(row);
			if (unknown) {
				input = opaque(input);
			}
			int emitted = 0;
			try (RowCursor cursor = new ExtensionCursor(input, new CopyBinding[] { copy }, row)) {
				while (row.advance(cursor)) {
					assertThat(((Literal) fixture.source.lazyValue(row.id(0))).intValue()).isEqualTo(emitted);
					String text = "unique-" + emitted + "😀";
					assertThat(((Literal) fixture.source.lazyValue(row.id(2))).intValue())
							.isEqualTo(text.codePointCount(0, text.length()));
					assertThat(((FactorizedRowCursor) cursor).multiplicity()).isEqualTo(1L);
					emitted++;
				}
			}
			assertThat(emitted).isEqualTo(128);
			assertThat(fixture.evaluations).hasValue(128);
			assertThat(row.boundMask()).isZero();
			assertThat(NativeExpressionDomain.SPILL_FILES_CREATED.get() - spills)
					.as(unknown ? "unknown physical costs must not silently choose a spillable memo"
							: "unique dependency cardinality proves that memoization cannot remove an evaluation")
					.isZero();
			assertThat(NativeExpressionDomain.IO_READ_OPERATIONS.get() - reads).isZero();
			assertThat(NativeExpressionDomain.IO_WRITE_OPERATIONS.get() - writes).isZero();
		} finally {
			restoreBudget(previousBudget);
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
		assertThat(manager.usedBytes()).isZero();
	}

	private static RowState automaticRow(NativeRowTermDomainExecutionTest.Fixture fixture) {
		RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
		assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, fixture.source, fixture.layout));
		return row;
	}

	private static RowCursor opaque(RowCursor delegate) {
		return new RowCursor() {
			@Override
			public boolean next() throws IOException {
				return delegate.next();
			}

			@Override
			public void close() {
				delegate.close();
			}
		};
	}

	private static void restoreBudget(String previous) {
		if (previous == null) {
			System.clearProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		} else {
			System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previous);
		}
	}
